type User { name: String!  posts: [Post!]! }
type Post { title: String! }

o title do post 2 falha:
  title  é String!    -> o post 2 não pode ser null
  [Post!]!            -> a lista não pode ter item null, então não pode ser null
  User.posts é !      -> posts não pode ser null
  user(id) é anulável -> user vira null

resultado:  { "data": { "user": null }, "errors": [ ... ] }

message Book {
	string title = 1;
	int32 year = 2;
}
service Library {
	rpc Get (BookId) returns (Book);                 // unary
	rpc Upload (stream Chunk) returns (Summary);     // client streaming
}
